#ifndef RTOS_TYPES_H
#define RTOS_TYPES_H

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

#define RTOS_MAX_PRIORITIES     32
#define RTOS_TICK_RATE_HZ       1000

typedef enum {
    RTOS_TASK_READY = 0,
    RTOS_TASK_RUNNING,
    RTOS_TASK_BLOCKED,
    RTOS_TASK_SUSPENDED
} rtos_task_state_t;

typedef enum {
    RTOS_OK = 0,
    RTOS_ERR_PARAM = -1,
    RTOS_ERR_FULL  = -2,
    RTOS_ERR_EMPTY = -3,
    RTOS_ERR_STATE = -4
} rtos_err_t;

typedef void (*rtos_task_func_t)(void *arg);

/*
 * Cấu trúc TCB (Task Control Block)
 * LƯU Ý: Con trỏ stack pointer (sp) BẮT BUỘC nằm ở offset 0 để mã hợp ngữ PendSV
 * có thể nạp/lưu trực tiếp qua con trỏ tcb mà không cần tính toán offset.
 */
typedef struct rtos_tcb {
    uint32_t            *sp;                /* Offset 0: Con trỏ đỉnh ngăn xếp hiện tại */
    uint32_t             priority;          /* Mức ưu tiên: 0 (cao nhất) -> 31 (thấp nhất) */
    rtos_task_state_t    state;             /* Trạng thái tác vụ */
    uint32_t             sleep_ticks;       /* Số tick cần ngủ nếu bị block định thời */
    uint32_t            *stack_base;        /* Đáy vùng nhớ stack */
    uint32_t             stack_size_words;  /* Kích thước stack tính theo word (4 bytes) */
    const char          *name;              /* Tên tác vụ phục vụ debug/giám sát */
    struct rtos_tcb     *next;              /* Con trỏ danh sách liên kết */
} rtos_tcb_t;

#endif /* RTOS_TYPES_H */

